"""Shared, positioned errors for each MiniSQL processing phase."""

from __future__ import annotations


class MiniSQLError(Exception):
    kind = "MiniSQL"

    def __init__(self, message: str, line: int | None = None,
                 column: int | None = None) -> None:
        super().__init__(message)
        self.message = message
        self.line = line
        self.column = column

    def __str__(self) -> str:
        if self.kind == "IO":
            return f"IOError: {self.message}"
        return (f"{self.kind}Error at line {self.line}, column {self.column}: "
                f"{self.message}")


class LexError(MiniSQLError):
    kind = "Lex"


class ParseError(MiniSQLError):
    kind = "Parse"


class SemanticError(MiniSQLError):
    kind = "Semantic"


class QueryRuntimeError(MiniSQLError):
    kind = "Runtime"


class DataIOError(MiniSQLError):
    kind = "IO"

    def __init__(self, message: str, line: int | None = None,
                 column: int | None = None) -> None:
        super().__init__(message)

"""Pure, deterministic CSV and aligned-table output."""

from __future__ import annotations

from .model import Result


def _value_text(value: int | float | str) -> str:
    return repr(value) if isinstance(value, float) else str(value)


def _csv_field(value: int | float | str | None) -> str:
    if value is None:
        return ""
    text = _value_text(value)
    if (
        not text
        or any(char in text for char in ',"\r\n')
        or text.startswith(" ")
        or text.endswith(" ")
    ):
        return '"' + text.replace('"', '""') + '"'
    return text


def format_csv(result: Result) -> str:
    """Return LF-terminated CSV, distinguishing NULL from empty TEXT."""
    lines = [",".join(_csv_field(name) for name in result.columns)]
    lines.extend(
        ",".join(_csv_field(value) for value in row) for row in result.rows
    )
    return "\n".join(lines) + "\n"


def _table_cell(value: int | float | str | None) -> str:
    text = "NULL" if value is None else _value_text(value)
    return text.replace("\r", "\\r").replace("\n", "\\n")


def format_table(result: Result) -> str:
    """Return an escaped, code-point-aligned table with a row-count footer."""
    headers = [_table_cell(name) for name in result.columns]
    rows = [[_table_cell(value) for value in row] for row in result.rows]
    widths = [len(header) for header in headers]
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))

    lines = [" | ".join(cell.ljust(width) for cell, width in zip(headers, widths))]
    lines.append("-+-".join("-" * width for width in widths))
    for values, cells in zip(result.rows, rows):
        lines.append(" | ".join(
            cell.rjust(width) if isinstance(value, (int, float)) else cell.ljust(width)
            for value, cell, width in zip(values, cells, widths)
        ))
    count = len(result.rows)
    lines.append(f"({count} {'row' if count == 1 else 'rows'})")
    return "\n".join(line.rstrip(" ") for line in lines) + "\n"

"""Discover CSV tables and infer types from complete, freshly read columns."""

from __future__ import annotations

import csv
from dataclasses import dataclass
from os import PathLike, fspath
from pathlib import Path
import re

from .errors import DataIOError, SemanticError


_INTEGER = re.compile(r"[+-]?[0-9]+")
_REAL = re.compile(r"[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)([eE][+-]?[0-9]+)?")


@dataclass(frozen=True)
class Table:
    name: str
    columns: list[str]
    types: list[str]
    rows: list[tuple]


class Catalog:
    def __init__(self, data_dir: str | PathLike[str]) -> None:
        directory = fspath(data_dir)
        self._path = Path(directory)
        if not self._path.is_dir():
            raise DataIOError(f"data directory not found: {directory}")

    def _files(self) -> list[Path]:
        try:
            return [path for path in self._path.iterdir()
                    if path.name.lower().endswith(".csv") and path.is_file()]
        except OSError as error:
            raise DataIOError(f"{self._path.name}: {error.strerror}") from error

    def tables(self) -> list[str]:
        return sorted((path.name[:-4] for path in self._files()),
                      key=lambda name: (name.lower(), name))

    def load(self, name: str, line: int = 1, column: int = 1) -> Table:
        matches = [path for path in self._files()
                   if path.name[:-4].lower() == name.lower()]
        if not matches:
            raise SemanticError(f"unknown table '{name}'", line, column)
        if len(matches) > 1:
            raise DataIOError(f"ambiguous table file '{name}'")
        path = matches[0]
        columns = None
        raw_rows = []
        try:
            with path.open(encoding="utf-8-sig", newline="") as stream:
                reader = csv.reader(stream, strict=True)
                try:
                    for fields in reader:
                        if not fields:
                            continue
                        if columns is None:
                            columns = fields
                            seen = set()
                            for header in columns:
                                if not header:
                                    raise DataIOError(f"{path.name}: empty column name")
                                if header.lower() in seen:
                                    raise DataIOError(
                                        f"{path.name}: duplicate column '{header}'")
                                seen.add(header.lower())
                        elif len(fields) != len(columns):
                            raise DataIOError(
                                f"{path.name}: line {reader.line_num}: expected "
                                f"{len(columns)} fields, got {len(fields)}")
                        else:
                            raw_rows.append(fields)
                except csv.Error as error:
                    raise DataIOError(
                        f"{path.name}: line {reader.line_num}: malformed CSV") from error
        except UnicodeDecodeError as error:
            raise DataIOError(f"{path.name}: invalid UTF-8") from error
        except OSError as error:
            raise DataIOError(f"{path.name}: {error.strerror}") from error
        if columns is None:
            raise DataIOError(f"{path.name}: empty file")

        types = []
        for index in range(len(columns)):
            fields = [row[index] for row in raw_rows if row[index] != ""]
            if fields and all(_INTEGER.fullmatch(field) for field in fields):
                types.append("INTEGER")
            elif fields and all(_REAL.fullmatch(field) for field in fields):
                types.append("REAL")
            else:
                types.append("TEXT")
        converters = {"INTEGER": int, "REAL": float, "TEXT": str}
        rows = [tuple(None if field == "" else converters[kind](field)
                      for field, kind in zip(row, types)) for row in raw_rows]
        return Table(path.name[:-4], columns, types, rows)

    def schema(self, name: str) -> list[tuple[str, str]]:
        table = self.load(name)
        return list(zip(table.columns, table.types))

"""Source-preserving syntax records, deliberately independent of binding.

All spans are zero-based, end-exclusive offsets into Query.source. Tokens retain
query spelling and positions. Parenthesized is explicit: consumers can ignore it
for structural identity, but must not ignore it for headings or bare ORDER BY.
"""

from __future__ import annotations

from dataclasses import dataclass

from .lexer import Token


@dataclass(frozen=True)
class Node:
    start: int
    end: int


@dataclass(frozen=True)
class Expr(Node):
    pass


@dataclass(frozen=True)
class Literal(Expr):
    token: Token


@dataclass(frozen=True)
class Column(Expr):
    name: Token
    qualifier: Token | None


@dataclass(frozen=True)
class Unary(Expr):
    operator: Token
    operand: Expr


@dataclass(frozen=True)
class Binary(Expr):
    left: Expr
    operator: Token
    right: Expr


@dataclass(frozen=True)
class IsNull(Expr):
    operand: Expr
    operator: Token
    not_token: Token | None
    null_token: Token


@dataclass(frozen=True)
class Like(Expr):
    operand: Expr
    operator: Token
    pattern: Expr
    not_token: Token | None
    escape_keyword: Token | None
    escape: Token | None


@dataclass(frozen=True)
class In(Expr):
    operand: Expr
    operator: Token
    items: tuple[Expr, ...]
    not_token: Token | None
    lparen: Token
    rparen: Token


@dataclass(frozen=True)
class Call(Expr):
    name: Token
    argument: Expr | None
    star: Token | None
    lparen: Token
    rparen: Token


@dataclass(frozen=True)
class Parenthesized(Expr):
    expression: Expr
    lparen: Token
    rparen: Token


@dataclass(frozen=True)
class Wildcard(Node):
    star: Token
    qualifier: Token | None


@dataclass(frozen=True)
class SelectItem(Node):
    expression: Expr | Wildcard
    alias: Token | None
    as_token: Token | None


@dataclass(frozen=True)
class TableRef(Node):
    name: Token
    alias: Token | None
    as_token: Token | None


@dataclass(frozen=True)
class Join(Node):
    kind: str  # INNER or LEFT, including an unadorned JOIN as INNER
    table: TableRef
    condition: Expr
    keyword: Token  # JOIN for bare JOIN, otherwise INNER or LEFT
    join_token: Token
    outer_token: Token | None
    on_token: Token


@dataclass(frozen=True)
class OrderItem(Node):
    expression: Expr
    direction: Token | None  # None means ASC


@dataclass(frozen=True)
class Query(Node):
    source: str
    select_token: Token
    distinct: Token | None
    items: tuple[SelectItem, ...]
    from_table: TableRef | None
    joins: tuple[Join, ...]
    where: Expr | None
    group_by: tuple[Expr, ...]
    having: Expr | None
    order_by: tuple[OrderItem, ...]
    limit: Token | None
    offset: Token | None
    semicolon: Token | None

"""Recursive-descent parser for exactly the contract's SELECT grammar."""

from __future__ import annotations

from . import ast
from .errors import ParseError
from .lexer import Token, tokenize


_NAMES = ("IDENT", "QUOTED_IDENT")
_COMPARISONS = ("=", "<>", "!=", "<", "<=", ">", ">=")


def parse(sql: str) -> ast.Query:
    """Lex the complete input before parsing, then return its sourceful AST."""
    return _Parser(sql, tokenize(sql)).query()


class _Parser:
    def __init__(self, source: str, tokens: list[Token]) -> None:
        self.source = source
        self.tokens = tokens
        self.index = 0

    @property
    def current(self) -> Token:
        return self.tokens[self.index]

    def error(self) -> None:
        token = self.current
        message = ("unexpected end of input" if token.kind == "EOF"
                   else f"unexpected token '{token.raw}'")
        raise ParseError(message, token.line, token.column)

    def match(self, *kinds: str) -> Token | None:
        if self.current.kind in kinds:
            token = self.current
            self.index += 1
            return token
        return None

    def expect(self, *kinds: str) -> Token:
        token = self.match(*kinds)
        if token is None:
            self.error()
        return token

    def query(self) -> ast.Query:
        select = self.expect("SELECT")
        distinct = self.match("DISTINCT")
        items = [self.item()]
        while self.match(","):
            items.append(self.item())

        from_table = None
        joins = []
        if self.match("FROM"):
            from_table = self.table()
            while self.current.kind in ("JOIN", "INNER", "LEFT"):
                joins.append(self.join())
        where = self.expression() if self.match("WHERE") else None
        group_by = []
        if self.match("GROUP"):
            self.expect("BY")
            group_by.append(self.expression())
            while self.match(","):
                group_by.append(self.expression())
        having = self.expression() if self.match("HAVING") else None
        order_by = []
        if self.match("ORDER"):
            self.expect("BY")
            order_by.append(self.order())
            while self.match(","):
                order_by.append(self.order())
        limit = self.expect("INT") if self.match("LIMIT") else None
        offset = self.expect("INT") if self.match("OFFSET") else None
        semicolon = self.match(";")
        end = self.tokens[self.index - 1].end
        self.expect("EOF")
        return ast.Query(
            select.start, end, self.source, select, distinct, tuple(items),
            from_table, tuple(joins), where, tuple(group_by), having,
            tuple(order_by), limit, offset, semicolon,
        )

    def alias(self) -> tuple[Token | None, Token | None]:
        as_token = self.match("AS")
        alias = self.expect(*_NAMES) if as_token else self.match(*_NAMES)
        return alias, as_token

    def item(self) -> ast.SelectItem:
        token = self.current
        if star := self.match("*"):
            expression = ast.Wildcard(star.start, star.end, star, None)
        elif (token.kind in _NAMES
              and self.tokens[self.index + 1].kind == "."
              and self.tokens[self.index + 2].kind == "*"):
            qualifier = self.expect(*_NAMES)
            self.expect(".")
            star = self.expect("*")
            expression = ast.Wildcard(qualifier.start, star.end, star, qualifier)
        else:
            expression = self.expression()
            alias, as_token = self.alias()
            end = alias.end if alias else expression.end
            return ast.SelectItem(expression.start, end, expression, alias,
                                  as_token)
        return ast.SelectItem(expression.start, expression.end, expression,
                              None, None)

    def table(self) -> ast.TableRef:
        name = self.expect(*_NAMES)
        alias, as_token = self.alias()
        return ast.TableRef(name.start, alias.end if alias else name.end,
                            name, alias, as_token)

    def join(self) -> ast.Join:
        keyword = self.expect("JOIN", "INNER", "LEFT")
        kind = "LEFT" if keyword.kind == "LEFT" else "INNER"
        outer = self.match("OUTER") if kind == "LEFT" else None
        join_token = keyword if keyword.kind == "JOIN" else self.expect("JOIN")
        table = self.table()
        on_token = self.expect("ON")
        condition = self.expression()
        return ast.Join(keyword.start, condition.end, kind, table, condition,
                        keyword, join_token, outer, on_token)

    def order(self) -> ast.OrderItem:
        expression = self.expression()
        direction = self.match("ASC", "DESC")
        return ast.OrderItem(expression.start,
                             direction.end if direction else expression.end,
                             expression, direction)

    def binary(self, operand, operators: tuple[str, ...]) -> ast.Expr:
        left = operand()
        while self.current.kind in operators:
            operator = self.expect(*operators)
            right = operand()
            left = ast.Binary(left.start, right.end, left, operator, right)
        return left

    def expression(self) -> ast.Expr:
        return self.binary(self.and_expression, ("OR",))

    def and_expression(self) -> ast.Expr:
        return self.binary(self.not_expression, ("AND",))

    def not_expression(self) -> ast.Expr:
        if operator := self.match("NOT"):
            operand = self.not_expression()
            return ast.Unary(operator.start, operand.end, operator, operand)
        return self.comparison()

    def comparison(self) -> ast.Expr:
        left = self.add()
        if operator := self.match(*_COMPARISONS):
            right = self.add()
            return ast.Binary(left.start, right.end, left, operator, right)
        if operator := self.match("IS"):
            not_token = self.match("NOT")
            null = self.expect("NULL")
            return ast.IsNull(left.start, null.end, left, operator, not_token,
                              null)
        not_token = self.match("NOT")
        if operator := self.match("LIKE"):
            pattern = self.add()
            escape_keyword = self.match("ESCAPE")
            escape = self.expect("STRING") if escape_keyword else None
            return ast.Like(left.start, escape.end if escape else pattern.end,
                            left, operator, pattern, not_token, escape_keyword,
                            escape)
        if operator := self.match("IN"):
            lparen = self.expect("(")
            items = [self.expression()]
            while self.match(","):
                items.append(self.expression())
            rparen = self.expect(")")
            return ast.In(left.start, rparen.end, left, operator, tuple(items),
                          not_token, lparen, rparen)
        if not_token:
            self.error()
        return left

    def add(self) -> ast.Expr:
        return self.binary(self.multiply, ("+", "-"))

    def multiply(self) -> ast.Expr:
        return self.binary(self.unary, ("*", "/", "%"))

    def unary(self) -> ast.Expr:
        if operator := self.match("+", "-"):
            operand = self.unary()
            return ast.Unary(operator.start, operand.end, operator, operand)
        return self.primary()

    def primary(self) -> ast.Expr:
        if token := self.match("INT", "REAL", "STRING", "NULL"):
            return ast.Literal(token.start, token.end, token)
        if lparen := self.match("("):
            expression = self.expression()
            rparen = self.expect(")")
            return ast.Parenthesized(lparen.start, rparen.end, expression,
                                     lparen, rparen)
        name = self.expect(*_NAMES)
        if lparen := self.match("("):
            star = self.match("*")
            argument = None if star else self.expression()
            rparen = self.expect(")")
            return ast.Call(name.start, rparen.end, name, argument, star,
                            lparen, rparen)
        if self.match("."):
            column = self.expect(*_NAMES)
            return ast.Column(name.start, column.end, column, name)
        return ast.Column(name.start, name.end, name, None)

