"""Resolve and type a complete query before the executor evaluates any row."""

from __future__ import annotations

from dataclasses import dataclass, replace

from . import ast
from .catalog import Catalog, Table
from .errors import SemanticError
from .lexer import Token
from .model import integer_text


_NUMERIC = {"INTEGER", "REAL", "NULL"}
_AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
_COMPARISONS = {"=", "<>", "!=", "<", "<=", ">", ">="}


@dataclass(frozen=True)
class BoundExpr:
    kind: str
    type: str
    source: ast.Node
    children: tuple[BoundExpr, ...] = ()
    value: object = None
    token: Token | None = None
    slot: int | None = None

    @property
    def key(self) -> tuple:
        """Source-independent identity; group references retain their old key."""
        if self.kind == "group":
            return self.value
        return (self.kind, self.type, self.value,
                tuple(child.key for child in self.children))


@dataclass(frozen=True)
class Range:
    name: str
    table: Table
    offset: int


@dataclass(frozen=True)
class BoundJoin:
    kind: str
    range: Range
    condition: BoundExpr


@dataclass(frozen=True)
class BoundOrder:
    expression: BoundExpr | None
    output_index: int | None
    descending: bool


@dataclass(frozen=True)
class BoundQuery:
    ranges: tuple[Range, ...]
    joins: tuple[BoundJoin, ...]
    where: BoundExpr | None
    group_by: tuple[BoundExpr, ...]
    aggregates: tuple[BoundExpr, ...]
    aggregate_query: bool
    having: BoundExpr | None
    select: tuple[BoundExpr, ...]
    columns: list[str]
    order_by: tuple[BoundOrder, ...]
    distinct: bool
    limit: int | None
    offset: int


def bind(query: ast.Query, catalog: Catalog) -> BoundQuery:
    return _Binder(query, catalog).bind()


class _Binder:
    def __init__(self, query: ast.Query, catalog: Catalog) -> None:
        self.query = query
        self.catalog = catalog
        self.ranges: list[Range] = []
        self.aggregates: list[BoundExpr] = []

    def error(self, message: str, source: ast.Node | Token) -> None:
        if isinstance(source, Token):
            line, column = source.line, source.column
        else:
            prefix = self.query.source[:source.start]
            line = prefix.count("\n") + 1
            column = source.start - prefix.rfind("\n")
        raise SemanticError(message, line, column)

    def add_range(self, reference: ast.TableRef) -> Range:
        token = reference.alias or reference.name
        table = self.catalog.load(reference.name.value,
                                  reference.name.line, reference.name.column)
        if any(r.name.lower() == token.value.lower() for r in self.ranges):
            self.error(f"duplicate table name '{token.value}'", token)
        offset = sum(len(r.table.columns) for r in self.ranges)
        result = Range(token.value, table, offset)
        self.ranges.append(result)
        return result

    def column(self, source: ast.Column) -> BoundExpr:
        matches = []
        for range_ in self.ranges:
            if (source.qualifier is not None
                    and range_.name.lower() != source.qualifier.value.lower()):
                continue
            for index, name in enumerate(range_.table.columns):
                if name.lower() == source.name.value.lower():
                    matches.append((range_, index))
        reference = self.reference(source)
        if len(matches) != 1:
            adjective = "unknown" if not matches else "ambiguous"
            self.error(f"{adjective} column '{reference}'", source)
        range_, index = matches[0]
        return BoundExpr("column", range_.table.types[index], source,
                         value=range_.offset + index)

    @staticmethod
    def reference(source: ast.Column) -> str:
        return ((source.qualifier.value + ".") if source.qualifier else "") + source.name.value

    def mismatch(self, operator: Token, *operands: BoundExpr) -> None:
        types = " and ".join(operand.type for operand in operands)
        name = operator.value.upper() if operator.kind in ("IDENT", "QUOTED_IDENT") else operator.kind
        self.error(f"type mismatch: cannot apply '{name}' to {types}", operator)

    def comparable(self, left: BoundExpr, right: BoundExpr, operator: Token) -> None:
        if (left.type == "NULL" or right.type == "NULL"
                or left.type in _NUMERIC and right.type in _NUMERIC
                or left.type == right.type == "TEXT"):
            return
        self.mismatch(operator, left, right)

    def condition(self, source: ast.Expr, aggregate: bool = False) -> BoundExpr:
        expression = self.expression(source, aggregate)
        if expression.type not in _NUMERIC:
            self.error(f"condition must be numeric, got {expression.type}", source)
        return expression

    def expression(self, source: ast.Expr, aggregate: bool) -> BoundExpr:
        if isinstance(source, ast.Parenthesized):
            return self.expression(source.expression, aggregate)
        if isinstance(source, ast.Literal):
            type_ = {"INT": "INTEGER", "REAL": "REAL", "STRING": "TEXT", "NULL": "NULL"}[source.token.kind]
            value = None if type_ == "NULL" else source.token.value
            return BoundExpr("literal", type_, source, value=value)
        if isinstance(source, ast.Column):
            return self.column(source)
        if isinstance(source, ast.Call):
            name = source.name.value.upper()
            if name not in _AGGREGATES:
                self.error(f"unknown function '{source.name.value}'", source.name)
            if not aggregate:
                self.error("aggregate function not allowed here", source.name)
            if source.star is not None and name != "COUNT":
                self.error("'*' argument only allowed for COUNT", source.star)
            children = (() if source.star is not None
                        else (self.expression(source.argument, False),))
            if name in ("SUM", "AVG") and children[0].type not in _NUMERIC:
                self.mismatch(source.name, children[0])
            type_ = ("INTEGER" if name == "COUNT" else "REAL" if name == "AVG"
                     else children[0].type)
            result = BoundExpr("aggregate", type_, source, children, name,
                               source.name, len(self.aggregates))
            self.aggregates.append(result)
            return result
        if isinstance(source, ast.Unary):
            child = self.expression(source.operand, aggregate)
            if child.type not in _NUMERIC:
                self.mismatch(source.operator, child)
            type_ = "INTEGER" if source.operator.kind == "NOT" else child.type
            return BoundExpr("unary", type_, source, (child,),
                             source.operator.kind, source.operator)
        if isinstance(source, ast.Binary):
            left = self.expression(source.left, aggregate)
            right = self.expression(source.right, aggregate)
            operator = source.operator.kind
            if operator in _COMPARISONS:
                self.comparable(left, right, source.operator)
                type_ = "INTEGER"
            else:
                if left.type not in _NUMERIC or right.type not in _NUMERIC:
                    self.mismatch(source.operator, left, right)
                type_ = ("INTEGER" if operator in ("AND", "OR")
                         else "REAL" if "REAL" in (left.type, right.type)
                         else "NULL" if left.type == right.type == "NULL"
                         else "INTEGER")
            return BoundExpr("binary", type_, source, (left, right), operator,
                             source.operator)
        if isinstance(source, ast.IsNull):
            child = self.expression(source.operand, aggregate)
            return BoundExpr("is_null", "INTEGER", source, (child,),
                             source.not_token is not None, source.operator)
        if isinstance(source, ast.Like):
            left = self.expression(source.operand, aggregate)
            right = self.expression(source.pattern, aggregate)
            if left.type not in ("TEXT", "NULL") or right.type not in ("TEXT", "NULL"):
                self.mismatch(source.operator, left, right)
            if source.escape is not None and len(source.escape.value) != 1:
                self.error("ESCAPE must be a single character", source.escape)
            value = (source.not_token is not None,
                     source.escape.value if source.escape is not None else None)
            return BoundExpr("like", "INTEGER", source, (left, right), value,
                             source.operator)
        if isinstance(source, ast.In):
            left = self.expression(source.operand, aggregate)
            items = tuple(self.expression(item, aggregate) for item in source.items)
            for item in items:
                self.comparable(left, item, source.operator)
            return BoundExpr("in", "INTEGER", source, (left,) + items,
                             source.not_token is not None, source.operator)
        raise AssertionError(f"unhandled AST expression: {type(source).__name__}")

    def grouped(self, expression: BoundExpr, keys: dict[tuple, int]) -> BoundExpr:
        if expression.key in keys:
            return BoundExpr("group", expression.type, expression.source,
                             value=expression.key, slot=keys[expression.key])
        if expression.kind in ("aggregate", "literal"):
            return expression
        if expression.kind == "column":
            self.error(f"column '{self.reference(expression.source)}' must appear "
                       "in GROUP BY or be used in an aggregate", expression.source)
        return replace(expression, children=tuple(self.grouped(child, keys)
                                                 for child in expression.children))

    def bind(self) -> BoundQuery:
        query = self.query
        joins = []
        if query.from_table is not None:
            self.add_range(query.from_table)
        for join in query.joins:
            range_ = self.add_range(join.table)
            joins.append(BoundJoin(join.kind, range_, self.condition(join.condition)))
        where = self.condition(query.where) if query.where is not None else None
        group_by = tuple(self.expression(key, False) for key in query.group_by)
        select = []
        columns = []
        aliases: dict[str, list[int]] = {}
        wildcards = []
        for item in query.items:
            source = item.expression
            if isinstance(source, ast.Wildcard):
                wildcards.append(source)
                ranges = self.ranges
                if source.qualifier is not None:
                    ranges = [r for r in ranges if r.name.lower() == source.qualifier.value.lower()]
                    if not ranges:
                        self.error(f"unknown table '{source.qualifier.value}'", source.qualifier)
                for range_ in ranges:
                    for index, name in enumerate(range_.table.columns):
                        select.append(BoundExpr("column", range_.table.types[index],
                                                source, value=range_.offset + index))
                        columns.append(name)
                continue
            expression = self.expression(source, True)
            if item.alias is not None:
                name = item.alias.value
                aliases.setdefault(name.lower(), []).append(len(select))
            elif isinstance(source, ast.Column):
                index = expression.value
                range_ = next(r for r in self.ranges
                              if r.offset <= index < r.offset + len(r.table.columns))
                name = range_.table.columns[index - range_.offset]
            else:
                name = query.source[source.start:source.end]
            select.append(expression)
            columns.append(name)
        having = self.condition(query.having, True) if query.having is not None else None
        order_by = []
        for item in query.order_by:
            source = item.expression
            output_index = None
            expression = None
            if isinstance(source, ast.Literal) and source.token.kind == "INT":
                ordinal = source.token.value
                if not 1 <= ordinal <= len(select):
                    self.error(f"ORDER BY position {integer_text(ordinal)} is out of range", source)
                output_index = ordinal - 1
            elif (isinstance(source, ast.Column) and source.qualifier is None
                  and source.name.value.lower() in aliases):
                matches = aliases[source.name.value.lower()]
                if len(matches) != 1:
                    self.error(f"ambiguous column '{source.name.value}'", source)
                output_index = matches[0]
            else:
                expression = self.expression(source, True)
                if query.distinct is not None and not any(expression.key == e.key for e in select):
                    self.error("ORDER BY expression must appear in select list when DISTINCT is used", source)
            order_by.append(BoundOrder(expression, output_index,
                                       item.direction is not None and item.direction.kind == "DESC"))
        aggregate_query = bool(group_by or query.having is not None or self.aggregates)
        if aggregate_query:
            if wildcards:
                self.error("'*' not allowed in aggregate query", wildcards[0].star)
            keys = {expression.key: index for index, expression in enumerate(group_by)}
            select = [self.grouped(expression, keys) for expression in select]
            if having is not None:
                having = self.grouped(having, keys)
            order_by = [replace(order, expression=self.grouped(order.expression, keys))
                        if order.expression is not None else order for order in order_by]
        return BoundQuery(tuple(self.ranges), tuple(joins), where, group_by,
                          tuple(self.aggregates), aggregate_query, having, tuple(select),
                          columns, tuple(order_by), query.distinct is not None,
                          query.limit.value if query.limit is not None else None,
                          query.offset.value if query.offset is not None else 0)

